-- Ledger v9.6 and label crosswalk v9.7: test load. Unreviewed. Not decision-grade.
-- Safe to re-run: existing ids are skipped.

create table if not exists gsi_ledger_test (record_id text primary key, month text, investor_group text, investing_entity text, target_or_event text, destination_country text, flow_direction text, event_type text, transaction_status text, inclusion_decision text, investor_specific_amount_millions text, currency text, amount_scope text, announcement_or_report_date text, primary_source text, independent_source text, verified_claim_and_caveat text, next_verification text, linked_existing_record text, completion_date text, source_version text default 'v9.6');
alter table gsi_ledger_test enable row level security;
drop policy if exists "read test rows" on gsi_ledger_test;
create policy "read test rows" on gsi_ledger_test for select using (true);
on conflict (record_id) do nothing;

create table if not exists gsi_crosswalk_test (master_record_id text primary key, investor_group text, original_evidence_grade text, normalised_evidence_grade text, grade_mapping_basis text, original_transaction_status text, normalised_status_family text, status_mapping_basis text, crosswalk_version text, created_on text, source_version text default 'v9.7');
alter table gsi_crosswalk_test enable row level security;
drop policy if exists "read test rows" on gsi_crosswalk_test;
create policy "read test rows" on gsi_crosswalk_test for select using (true);
on conflict (master_record_id) do nothing;
